<?php
declare(strict_types=1);

/**
 * Lightweight hierarchical memory for DCP's first release.
 * Markdown is the human-readable source; JSON is the indexed state/cache.
 * This is a temporary DCP subsystem, not DP_MEMORY and not a replacement
 * for the future memory-core/Cognee gateway.
 */
final class MarkdownJsonMemory {
 private string $root;
 private string $indexFile;
 private string $lockFile;
 private int $maxSnippetBytes=1600;
 private array $levels=['global'=>0,'projects'=>1,'tasks'=>2,'sessions'=>3,'agents'=>4];
 public function __construct(string $userDataRoot){
  $this->root=rtrim($userDataRoot,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR.'memory';
  $this->indexFile=$this->root.DIRECTORY_SEPARATOR.'index.json';
  $this->lockFile=$this->root.DIRECTORY_SEPARATOR.'.memory.lock';
  foreach(['global','projects','tasks','sessions','agents','archive'] as $dir)$this->ensureDirectory($this->root.DIRECTORY_SEPARATOR.$dir);
  if(!is_file($this->indexFile))$this->writeIndex(['schema_version'=>1,'updated_at'=>date(DATE_ATOM),'records'=>[]]);
 }
 private function ensureDirectory(string $dir):void{if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('Cannot create DCP memory directory.');@chmod($dir,0700);}
 private function lock(callable $fn):mixed{$h=fopen($this->lockFile,'c');if(!$h)throw new RuntimeException('Cannot open DCP memory lock.');try{if(!flock($h,LOCK_EX))throw new RuntimeException('Cannot lock DCP memory index.');return $fn();}finally{flock($h,LOCK_UN);fclose($h);}}
 private function readIndex():array{$d=is_file($this->indexFile)?json_decode((string)file_get_contents($this->indexFile),true):null;if(!is_array($d)||($d['schema_version']??null)!==1||!is_array($d['records']??null))return ['schema_version'=>1,'updated_at'=>date(DATE_ATOM),'records'=>[]];return $d;}
 private function writeIndex(array $d):void{$d['updated_at']=date(DATE_ATOM);$tmp=$this->indexFile.'.'.bin2hex(random_bytes(5)).'.tmp';$bytes=json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n";if(file_put_contents($tmp,$bytes,LOCK_EX)===false)throw new RuntimeException('Cannot write DCP memory index.');@chmod($tmp,0600);if(!rename($tmp,$this->indexFile)){@unlink($tmp);throw new RuntimeException('Cannot atomically replace DCP memory index.');}@chmod($this->indexFile,0600);}
 private function redact(string $s):string{$patterns=[ '/(?i)(api[_-]?key|client[_-]?secret|access[_-]?token|refresh[_-]?token|password|passwd|secret)(\s*[=:]\s*)([^\s,;"\']+)/','$1$2[REDACTED]' ];$s=preg_replace($patterns[0],$patterns[1],$s)??$s;$s=preg_replace('/\bBearer\s+[A-Za-z0-9._~+\/-]+=*/i','Bearer [REDACTED]',$s)??$s;$s=preg_replace('/\b(?:sk|pk|ghp|gho|github_pat|xox[baprs])-[-A-Za-z0-9_]{12,}\b/','[REDACTED:secret]',$s)??$s;return $s;}
 private function slug(string $s):string{$s=strtolower(trim($s));$s=preg_replace('/[^a-z0-9_-]+/','-',$s)??'';$s=trim($s,'-');return substr($s?:'general',0,48);}
 private function pathFor(string $id,string $level,string $project):string{$folder=match($level){'global'=>'global','project'=>'projects/'.$this->slug($project),'task'=>'tasks/'.$this->slug($project),'session'=>'sessions/'.$this->slug($project),'agent'=>'agents/'.$this->slug($project),default=>throw new InvalidArgumentException('Unsupported DCP memory level.')};$this->ensureDirectory($this->root.'/'.$folder);return $folder.'/'.$this->slug($id).'.md';}
 private function parseFrontMatter(string $md):array{if(!preg_match('/^---\s*\R(.*?)\R---\s*\R/s',$md,$m))return []; $meta=[];foreach(preg_split('/\R/',$m[1]) as $line){if(preg_match('/^([a-z_]+):\s*(.*?)\s*$/',$line,$x))$meta[$x[1]]=trim($x[2]," \t\"'");}return $meta;}
 private function body(string $md):string{return preg_replace('/^---\s*\R.*?\R---\s*\R/s','',$md,1)??$md;}
 private function indexMarkdown(array &$index):void{$files=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($this->root,FilesystemIterator::SKIP_DOTS));foreach($files as $file){if(!$file->isFile()||strtolower($file->getExtension())!=='md')continue;$abs=$file->getPathname();$rel=substr($abs,strlen($this->root)+1);$md=(string)file_get_contents($abs);$meta=$this->parseFrontMatter($md);$id=(string)($meta['id']??pathinfo($abs,PATHINFO_FILENAME));if($id==='')continue;$body=$this->body($md);$index['records'][$id]=['id'=>$id,'level'=>(string)($meta['level']??'project'),'project'=>(string)($meta['project']??''),'agent'=>(string)($meta['agent']??'any'),'visibility'=>(string)($meta['visibility']??'private'),'status'=>(string)($meta['status']??'active'),'tags'=>isset($meta['tags'])?array_values(array_filter(array_map('trim',explode(',',trim($meta['tags'],'[] '))))):[],'title'=>(string)($meta['title']??$id),'summary'=>(string)($meta['summary']??substr(trim($body),0,240)),'path'=>$rel,'updated'=>(string)($meta['updated']??date(DATE_ATOM)),'content_hash'=>hash('sha256',$md)];}}
 public function remember(array $input):array{
  $id=(string)($input['id']??('mem_'.bin2hex(random_bytes(8))));$title=trim((string)($input['title']??''));$content=trim((string)($input['content']??''));$level=(string)($input['level']??'project');$project=(string)($input['project']??'');$agent=(string)($input['agent']??'any');$tags=$input['tags']??[];
  if(!preg_match('/^[A-Za-z0-9_-]{1,100}$/',$id)||$title===''||$content===''||strlen($title)>240||strlen($content)>20000||!in_array($level,['global','project','task','session','agent'],true)||!is_array($tags)||count($tags)>20)throw new InvalidArgumentException('DCP memory record is invalid or exceeds limits.');
  $title=$this->redact($title);$content=$this->redact($content);$summary=$this->redact((string)($input['summary']??substr($content,0,240)));$path=$this->pathFor($id,$level,$project);$updated=date(DATE_ATOM);$front="---\nid: {$id}\nlevel: {$level}\nproject: ".$this->slug($project)."\nagent: ".$this->slug($agent)."\nvisibility: private\nstatus: active\ntags: [".implode(', ',array_map(fn($t)=>$this->slug((string)$t),$tags))."]\nupdated: {$updated}\ntitle: \"".str_replace('"','\\"',$title)."\"\nsummary: \"".str_replace('"','\\"',$summary)."\"\n---\n\n# {$title}\n\n{$content}\n";
  return $this->lock(function()use($id,$front,$path,$updated,$title,$summary,$level,$project,$agent,$tags){$abs=$this->root.'/'.$path;$tmp=$abs.'.'.bin2hex(random_bytes(4)).'.tmp';if(file_put_contents($tmp,$front,LOCK_EX)===false)throw new RuntimeException('Cannot write DCP Markdown memory.');@chmod($tmp,0600);if(!rename($tmp,$abs)){@unlink($tmp);throw new RuntimeException('Cannot replace DCP Markdown memory.');}@chmod($abs,0600);$idx=$this->readIndex();$this->indexMarkdown($idx);$idx['records'][$id]['title']=$title;$idx['records'][$id]['summary']=$summary;$idx['records'][$id]['level']=$level;$idx['records'][$id]['project']=$project;$idx['records'][$id]['agent']=$agent;$idx['records'][$id]['tags']=$tags;$idx['records'][$id]['updated']=$updated;$idx['records'][$id]['path']=$path;$this->writeIndex($idx);return ['id'=>$id,'path'=>$path,'updated_at'=>$updated,'content_hash'=>hash('sha256',$front)];});
 }
 public function bootstrap(string $project,string $agent='any',int $limit=8):array{$project=$this->slug($project);$agent=$this->slug($agent);$limit=max(1,min($limit,12));$idx=$this->lock(function(){$d=$this->readIndex();$this->indexMarkdown($d);$this->writeIndex($d);return $d;});$records=array_values(array_filter($idx['records'],fn($r)=>($r['status']??'active')==='active'&&in_array(($r['visibility']??'private'),['private','team'],true)&&(($r['project']??'')===$project||($r['level']??'')==='global')&&(($r['agent']??'any')==='any'||($r['agent']??'')===$agent)));usort($records,fn($a,$b)=>strcmp((string)$b['updated'],(string)$a['updated']));return ['project'=>$project,'agent'=>$agent,'items'=>array_slice(array_map(fn($r)=>$this->preview($r),$records),0,$limit)];}
 public function recall(string $query,string $project='',string $agent='any',int $limit=5):array{$project=$this->slug($project);$agent=$this->slug($agent);$query=trim($query);if($query===''||strlen($query)>2000)throw new InvalidArgumentException('Memory query is empty or too long.');$idx=$this->lock(function(){$d=$this->readIndex();$this->indexMarkdown($d);$this->writeIndex($d);return $d;});$terms=array_values(array_unique(array_filter(preg_split('/[^\pL\pN_]+/u',mb_strtolower($query))?:[],fn($w)=>mb_strlen($w)>=3)));$rank=[];foreach($idx['records'] as $r){if(($r['status']??'active')!=='active'||(($r['project']??'')!==$project&&($r['level']??'')!=='global')||(($r['agent']??'any')!=='any'&&($r['agent']??'')!==$agent))continue;$hay=mb_strtolower(implode(' ',[$r['title']??'',$r['summary']??'',implode(' ',$r['tags']??[])]));$score=0;foreach($terms as $term)if(mb_strpos($hay,$term)!==false)$score+=1+min(2,mb_strlen($term)/10);if($score>0)$rank[]=[$score,$r];}usort($rank,fn($a,$b)=>$b[0]<=>$a[0]?:strcmp((string)$b[1]['updated'],(string)$a[1]['updated']));return array_map(fn($x)=>$this->preview($x[1]),array_slice($rank,0,max(1,min($limit,8))));}
 private function preview(array $r):array{return ['id'=>$r['id'],'level'=>$r['level'],'project'=>$r['project'],'agent'=>$r['agent'],'title'=>$r['title'],'summary'=>$r['summary'],'tags'=>$r['tags'],'updated'=>$r['updated'],'path'=>$r['path']];}
 public function read(string $id):array{$idx=$this->readIndex();$r=$idx['records'][$id]??null;if(!is_array($r)||($r['status']??'active')!=='active')throw new RuntimeException('Memory record not found.');$path=$this->root.'/'.$r['path'];$realRoot=realpath($this->root);$real=realpath($path);if(!$realRoot||!$real||!str_starts_with($real,$realRoot.DIRECTORY_SEPARATOR))throw new RuntimeException('Memory path escaped the DCP vault.');return ['metadata'=>$this->preview($r),'content'=>$this->redact($this->body((string)file_get_contents($real)))];}
 public function retire(string $id,string $reason):array{$reason=$this->redact(trim($reason));if($reason===''||strlen($reason)>1000)throw new InvalidArgumentException('Memory retirement needs a short reason.');return $this->lock(function()use($id,$reason){$idx=$this->readIndex();$r=$idx['records'][$id]??null;if(!is_array($r))throw new RuntimeException('Memory record not found.');$abs=$this->root.'/'.$r['path'];if(!is_file($abs))throw new RuntimeException('Memory Markdown source file is missing.');$md=(string)file_get_contents($abs);$md=preg_replace('/^status: active$/m','status: retired',$md,1)??$md;$md.="\n\n> Retired: {$reason}\n";if(file_put_contents($abs,$md,LOCK_EX)===false)throw new RuntimeException('Cannot update retired Markdown memory.');@chmod($abs,0600);$r['status']='retired';$r['retired_at']=date(DATE_ATOM);$r['retirement_reason']=$reason;$r['content_hash']=hash('sha256',$md);$idx['records'][$id]=$r;$this->writeIndex($idx);return ['id'=>$id,'status'=>'retired','history_preserved'=>true];});}
 public function export():array{return $this->lock(function(){$idx=$this->readIndex();$this->indexMarkdown($idx);$this->writeIndex($idx);return ['index'=>$this->indexFile,'root'=>$this->root,'count'=>count($idx['records']),'format'=>'Markdown + JSON'];});}
}
